import {loadPcb,mountPcb} from './pcb-viewer.js';
import {BOARDS,pinProfile} from './hardware-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(b,f)=>`hardware/${b}/${f}`;
let selected='ch347',tab='schematic',side='both',bus='i2c',disposeViewer=()=>{},generation=0;
export function hardwareHero(){return `<figure class="hardware-hero cad-product-pair"><div><img src="hardware/ch347/board-render.png" alt="CH347 板卡 CAD 渲染，保留原始管脚丝印"><span>CH347T</span></div><div><img src="hardware/rp2040/board-render.png" alt="RP2040 板卡 CAD 渲染，保留原始管脚丝印"><span>RP2040</span></div><figcaption>原始 PCB 与丝印 · KiCad 装配渲染</figcaption></figure>`;}
export function hardwareCards(){return `<div class="hardware-cards">${Object.entries(BOARDS).map(([key,b])=>`<article class="panel hardware-card"><button class="board-photo" data-hardware="${key}" aria-label="查看 ${b.name} 工程"><img src="${asset(key,'board-render.png')}" alt="${b.name} 的 KiCad 器件装配渲染" loading="lazy"></button><div class="hardware-card-body"><span class="eyebrow">${b.chip} · 35 × 16.5 mm</span><h2>${b.name}</h2><p>${b.desc}</p><div class="buttons"><button data-hardware="${key}" class="primary small">在线查看工程 ↗</button><a class="download-link" href="${asset(key,b.zip)}" download>工程 ZIP ↓</a></div></div></article>`).join('')}</div>`;}
export function hardwarePage(){const b=BOARDS[selected];return `${hardwareCards()}<section class="panel hardware-viewer-panel" id="hardware-viewer-panel"><div class="panel-header"><h2>工程查看器</h2><select id="hardware-board" aria-label="查看哪块调试器">${Object.entries(BOARDS).map(([k,b])=>`<option value="${k}" ${k===selected?'selected':''}>${b.name}</option>`).join('')}</select></div><div class="cad-toolbar"><div class="cad-tabs" role="tablist" aria-label="工程视图">${[['schematic','原理图'],['pcb','PCB'],['3d','3D 装配']].map(([k,v])=>`<button role="tab" aria-selected="${tab===k}" data-cad-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div><div class="cad-controls">${tab==='3d'?'<button class="small" data-cad-face="top">正面丝印</button><button class="small" data-cad-face="bottom">背面丝印</button>':''}${tab==='pcb'?`<select id="pcb-side" aria-label="PCB 面"><option value="both" ${side==='both'?'selected':''}>双层叠加 · F.Cu + B.Cu</option><option value="front" ${side==='front'?'selected':''}>正面 · F.Cu</option><option value="back" ${side==='back'?'selected':''}>背面 · B.Cu</option></select>`:''}<button class="small" data-cad-zoom="in" aria-label="放大工程">＋</button><button class="small" data-cad-zoom="out" aria-label="缩小工程">−</button><button class="small" data-cad-reset>复位视图</button><button class="small" data-cad-expand>展开</button></div></div>${tab==='pcb'?`<div class="pcb-net-bar" id="pcb-net-bar"><div class="pcb-net-tools"><span class="pcb-legend front">● F.Cu 顶层</span><span class="pcb-legend back">● B.Cu 底层</span><label><input type="checkbox" id="pcb-show-silk" checked>显示${side==='back'?'背面':'正面'}丝印</label><select id="pcb-net-select" aria-label="PCB 网络" disabled><option>正在加载网络…</option></select><button class="small" data-net-clear disabled>清除高亮</button></div><div class="pcb-net-details" role="status" aria-live="polite">点击走线、焊盘或过孔，查看整个网络。</div><div class="pcb-net-choices"></div></div>`:''}<div id="cad-stage" class="cad-stage ${tab==='3d'?'cad-3d':tab==='pcb'?'cad-pcb':''}" tabindex="0" aria-label="${b.name} ${tab==='3d'?'交互式三维模型':'矢量工程图'}" aria-describedby="cad-help"><span class="cad-loading">正在加载工程…</span></div><div class="cad-status"><span id="cad-help">${tab==='3d'?'拖动旋转 · 滚轮缩放 · 右键拖动平移':'滚轮缩放 · 拖动平移 · 双击复位 · 键盘 + / − / 方向键'}${tab==='pcb'?' · 单击选择网络 · Esc 清除高亮'+(side==='both'?' · 双层均从正面俯视':''):''}</span><a id="cad-source-link" ${tab==='pcb'?'aria-disabled="true"':`href="${asset(selected,tab==='schematic'?`schematic/${b.base}.svg`:'board.glb')}"`} download>下载当前${tab==='3d'?' GLB 模型':' SVG'} ↓</a></div><div class="panel-body hardware-downloads"><div><b>原始 KiCad 9 工程</b><p>工程文件保持原样；预览由 KiCad 9.0.9 导出。3D 按模型装配展示，选装件以实际焊接为准。</p><div class="buttons">${[['kicad_sch','原理图'],['kicad_pcb','PCB'],['kicad_pro','项目']].map(([ext,label])=>`<a class="download-link" href="${asset(selected,`source/${b.base}.${ext}`)}" download>${label} .${ext} ↓</a>`).join('')}<a class="download-link" href="${asset(selected,'board-render.png')}" download>CAD 渲染 PNG ↓</a><a class="download-link" href="hardware/manifest.json" download>来源与校验值 ↓</a></div></div><a class="download-link" href="${asset(selected,b.zip)}" download>下载完整工程 ZIP ↓</a></div></section><div class="notice">两款板卡的 J2 都是双面边缘排针：正面为 1 / 3 / 5 / 7 / 9 / 11，背面为 2 / 4 / 6 / 8 / 10 / 12。背面图按翻板后的视角显示。</div><div id="pin-context"></div>`;}
export function pinContext(state,getform){if(!['fpga','mcu','uart','flash','i2c','gpio','jtag','logic','scope','wiring','firmwares','hardware'].includes(state.page))return '';return '<div id="pin-context"></div>';}
function pinHTML(state,getform){const page=state.page==='hardware'?'wiring':state.page,mode=state.page==='hardware'?(selected==='rp2040'?4:3):state.mode,p=pinProfile(page,mode,getform(page),bus),b=BOARDS[p.board];const full=['wiring','firmwares'].includes(page);const mismatch=!full&&(state.mode>=4)!==(p.board==='rp2040');
 const pin=(i)=>{const n=i+1,a=p.active[n];return `<div class="pin-row ${a?'active '+a.kind:''}"><span class="pin-number">${n}</span><span class="pin-label"><b>${esc(a?.signal||b.pins[i])}</b>${a?`<small>${esc(a.target)}</small>`:''}</span><em class="pin-silk">丝印 ${b.silk[i]}</em></div>`;};
 return `<details class="panel pin-panel" open><summary><span>接线指引 <b>${b.name} · ${p.title}</b></span><span class="pill">${p.required}</span></summary><div class="pin-content">${state.page==='i2c'?`<div class="pin-bus-tabs"><span>当前接线</span><button class="small ${bus==='i2c'?'primary':''}" data-pin-bus="i2c">I²C</button><button class="small ${bus==='spi'?'primary':''}" data-pin-bus="spi">SPI</button></div>`:''}${mismatch?'<div class="warning">此页展示所需调试器的接线，当前选中的设备类型不匹配。请切换设备再执行。</div>':''}${state.device?.family==='rp2040'&&!state.device.board_match?'<div class="warning">当前 RP2040 尚未确认使用本板固件。以下接线仅适用于本工具提供的 LA_RP2040 固件。</div>':''}<div class="pin-grid"><div class="pin-photo"><img src="${asset(p.board,'board-top.png')}" alt="${b.name} 正面装配，USB 在左，J2 在右"><div class="pin-orientation"><span>← USB-C</span><b>正面俯视</b><span>J2 →</span></div><button class="small ghost" data-hardware="${p.board}">查看原理图 / PCB / 3D ↗</button><p>${esc(p.note)}</p></div><div class="pin-face"><div class="pin-face-title">正面 · 奇数脚 <small>USB 左 / J2 右</small></div>${[0,2,4,6,8,10].map(pin).join('')}</div><div class="pin-face back"><div class="pin-face-title">背面 · 偶数脚 <small>翻板后 USB 右 / J2 左</small></div>${[1,3,5,7,9,11].map(pin).join('')}</div></div><div class="pin-foot"><span><i class="pin-dot"></i>高亮 = 本功能信号 · 灰色 = 本次不用</span><span>J2-2 为 3.3 V 电源输出，不是 VTref${p.board==='rp2040'?'；J2-4 为 USB 5 V 电源':''}。</span></div></div></details>`;
}
export function cleanupHardware(){generation++;disposeViewer();disposeViewer=()=>{};}
export function bindHardware(state,getform,render,nav){
 const openBoard=(key)=>{selected=key;nav('hardware');document.querySelector('#hardware-viewer-panel')?.scrollIntoView({behavior:'smooth',block:'start'});};
 const bindBoardButtons=()=>document.querySelectorAll('[data-hardware]').forEach(el=>el.onclick=()=>openBoard(el.dataset.hardware));
 const update=()=>{const host=document.querySelector('#pin-context');if(!host)return;host.innerHTML=pinHTML(state,getform);host.querySelectorAll('[data-pin-bus]').forEach(el=>el.onclick=()=>{bus=el.dataset.pinBus;update();});bindBoardButtons();};update();bindBoardButtons();
 document.querySelectorAll('[data-field]').forEach(el=>{el.addEventListener('input',update);if(state.page==='i2c')el.addEventListener('focus',()=>{bus=['spi_mode','spi_data','freq'].includes(el.dataset.field)?'spi':'i2c';update();});});
 if(state.page==='i2c')document.querySelectorAll('[data-op]').forEach(el=>el.addEventListener('focus',()=>{bus=el.dataset.op.startsWith('spi.')?'spi':'i2c';update();}));
 if(state.page!=='hardware')return;
 document.querySelector('#hardware-board').onchange=e=>{selected=e.target.value;render();};
 document.querySelectorAll('[data-cad-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.cadTab;render();});
 const sideSelect=document.querySelector('#pcb-side');if(sideSelect)sideSelect.onchange=e=>{side=e.target.value;render();};
 document.querySelector('[data-cad-expand]').onclick=e=>{const panel=document.querySelector('#hardware-viewer-panel');panel.classList.toggle('expanded');e.target.textContent=panel.classList.contains('expanded')?'收起':'展开';};
 mountViewer();
}
async function mountViewer(){const host=document.querySelector('#cad-stage'),id=++generation,b=BOARDS[selected];
 try{
  if(tab==='3d'){
   const {mountBoard3D}=await import('./vendor/board3d.js');if(id!==generation||!host.isConnected)return;
   disposeViewer=mountBoard3D(host,asset(selected,'board.glb'),asset(selected,'board-render.png'));
  }else if(tab==='pcb'){
   const resources=await loadPcb(selected);if(id!==generation||!host.isConnected)return;disposeViewer=mountPcb(host,selected,side,resources,mount2D);
  }else{
   const img=new Image();img.alt=b.name+(tab==='schematic'?' 原理图':' PCB '+(side==='back'?'背面':'正面'));img.draggable=false;img.className='cad-image';img.src=asset(selected,tab==='schematic'?`schematic/${b.base}.svg`:`pcb-${side}.svg`);await img.decode();if(id!==generation||!host.isConnected)return;host.replaceChildren(img);disposeViewer=mount2D(host,img,tab==='pcb'&&side==='back');
  }
 }catch(e){if(id===generation&&host.isConnected)host.innerHTML=`<div class="cad-error">工程预览加载失败：${esc(e.message)}<br>可使用下方下载入口在 KiCad 中打开。</div>`;}
}
function mount2D(host,img,mirror,{onSelect,onClear}={}){let zoom=1,x=0,y=0,drag=null;const paint=()=>{img.style.transform=`translate(${x}px,${y}px) scale(${mirror?-zoom:zoom},${zoom})`;host.dataset.zoom=zoom.toFixed(2);};
 const scale=(factor,cx=0,cy=0)=>{const next=Math.max(.5,Math.min(24,zoom*factor)),r=next/zoom;x=cx-(cx-x)*r;y=cy-(cy-y)*r;zoom=next;paint();};
 const reset=()=>{zoom=1;x=y=0;paint();};
 host.onwheel=e=>{e.preventDefault();const r=host.getBoundingClientRect();scale(Math.exp(-e.deltaY*.002),e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2);};
 host.onpointerdown=e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};host.setPointerCapture(e.pointerId);host.classList.add('dragging');};
 host.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;if(!drag.moved&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<4)return;drag.moved=true;x+=e.clientX-drag.x;y+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;paint();};
 host.onpointerup=e=>{if(drag?.id===e.pointerId&&!drag.moved)onSelect?.(e);drag=null;host.classList.remove('dragging');};host.onpointercancel=()=>{drag=null;host.classList.remove('dragging');};host.ondblclick=reset;
 host.onkeydown=e=>{if(e.key==='Escape'){onClear?.();return;}if(['+','=','-','Home','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(['+','='].includes(e.key))scale(1.35);else if(e.key==='-')scale(1/1.35);else if(e.key==='Home')reset();else{x+=e.key==='ArrowLeft'?-40:e.key==='ArrowRight'?40:0;y+=e.key==='ArrowUp'?-40:e.key==='ArrowDown'?40:0;paint();}}};
 document.querySelector('[data-cad-zoom="in"]').onclick=()=>scale(1.4);document.querySelector('[data-cad-zoom="out"]').onclick=()=>scale(1/1.4);document.querySelector('[data-cad-reset]').onclick=reset;paint();
 return ()=>{host.onwheel=host.onpointerdown=host.onpointermove=host.onpointerup=host.onpointercancel=host.ondblclick=host.onkeydown=null;};
}
